INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(9109010, 1, 1, 'Is it warm? Is it? Go and check!', 0),
(9109011, 1, 1, 'Three fires, Snack, and then the nest. It''s getting cold!', 0),
(9109012, 1, 1, 'Three lessons, Snack. It''s writing to me as well now. The letters are getting longer.', 0),
(9109013, 1, 1, 'Is it warm? Is it? Go and check!', 0),
(9109014, 1, 1, 'Three fires, Snack, and then the nest. It''s getting cold!', 0),
(9109015, 1, 1, 'Three lessons, Snack. It''s writing to me as well now. The letters are getting longer.', 0),
(9109016, 1, 1, 'Is it warm? Is it? Go and check!', 0),
(9109017, 1, 1, 'Three fires, Snack, and then the nest. It''s getting cold!', 0),
(9109018, 1, 1, 'Three lessons, Snack. It''s writing to me as well now. The letters are getting longer.', 0),
(9109020, 1, 1, 'Five shards, Snack, in eight hours, as a flutterer. Is it still dreaming?', 0),
(9109021, 1, 1, 'Five shards, Snack, in eight hours, as a flutterer. Is it still dreaming?', 0),
(9109022, 1, 1, 'Five shards, Snack, in eight hours, as a flutterer. Is it still dreaming?', 0),
(9109023, 1, 1, 'Five shards, Snack, in eight hours, as a flutterer. Is it still dreaming?', 0),
(9109024, 1, 1, 'Five shards, Snack, in eight hours, as a flutterer. Is it still dreaming?', 0),
(9109025, 1, 1, 'Sit, little horror. Dreams come to the ones who stay still.', 0),
(9109030, 1, 1, 'Sniff, little horror. Stand still and sniff.', 0),
(9109031, 1, 1, 'The Lion''s Pride, Snack. Sniff. Tiny glint.', 0),
(9109032, 1, 1, 'Three silly places, Snack. Then think.', 0),
(9109033, 1, 1, 'Is she out? Are the camels home? Did she say ''under control''?', 0),
(9109034, 1, 1, 'Laugh LOUDER, Snack.', 0),
(9109050, 1, 1, 'The lantern is dark? Then pick up another. Steadily, this time.', 0),
(9109051, 1, 1, 'Dark again? The road is long. Walk it steadily.', 0),
(9109052, 1, 1, 'The Argent light is stubborn. So are you.', 0),
(9109053, 1, 1, 'The great light is dark? Then Icecrown keeps it a while longer. Go back.', 0),
(9109060, 1, 1, 'Hold the shape. Keep still. Let them sniff.', 0),
(9109061, 1, 1, 'Hold the shape. Keep still. Let them sniff.', 0),
(9109062, 1, 1, 'Hold the shape. Keep still. Let them sniff.', 0),
(9109063, 1, 1, 'Hold the shape. Keep still. Let them sniff.', 0),
(9109064, 1, 1, 'Hold the shape. Keep still. Let them sniff.', 0),
(9109065, 1, 1, 'Hold the shape. Keep still. Let them sniff.', 0),
(9109066, 1, 1, 'Hold the shape. Keep still. Let them sniff.', 0),
(9109070, 1, 1, 'The cauldron is waiting. So is Wren, with a name ready.', 0),
(9109071, 1, 1, 'The cauldron is waiting. So is Wren, with a name ready.', 0),
(9109072, 1, 1, 'The cauldron is waiting. So is Wren, with a name ready.', 0),
(9109073, 1, 1, 'The cauldron is waiting. So is Wren, with a name ready.', 0),
(9109074, 1, 1, 'The cauldron is waiting. So is Wren, with a name ready.', 0),
(9109075, 1, 1, 'The cauldron is waiting. So is Wren, with a name ready.', 0),
(9109076, 1, 1, 'The cauldron is waiting. So is Wren, with a name ready.', 0),
(9109080, 1, 1, 'The candle is not lit? It only burns at night, little horror.', 0),
(9109081, 1, 1, 'The candle is not lit? It only burns at night, little horror.', 0),
(9109082, 1, 1, 'The candle is not lit? It only burns at night, little horror.', 0),
(9109083, 1, 1, 'The candle is not lit? It only burns at night, little horror.', 0),
(9109084, 1, 1, 'The candle is not lit? It only burns at night, little horror.', 0),
(9109085, 1, 1, 'They are waiting at the Thin Place.', 0),
(9109086, 1, 1, 'They are circling. Eat something where they can see.', 0),
(9109090, 1, 1, 'Six places, and look properly. I can tell when you are not looking.', 0),
(9109091, 1, 1, 'Two more. The bay at sunset; the throne any time, they never stop arguing.', 0),
(9109100, 1, 1, 'Four lamps, Snack, at night. Fish are watching.', 0),
(9109101, 1, 1, 'Watch the water, Snack. At night.', 0),
(9109102, 1, 1, 'Lights, then the pier, then patting. No eating.', 0),
(9109103, 1, 1, 'The fjord is cold. The glider is colder. Wait.', 0),
(9109110, 1, 1, 'The bell is not rung. Climb.', 0),
(9109111, 1, 1, 'The bell is not rung. Climb.', 0),
(9109112, 1, 1, 'The bell is not rung. Climb.', 0),
(9109113, 1, 1, 'The bell is not rung. Climb.', 0),
(9109114, 1, 1, 'An hour, little horror. All four. On foot.', 0),
(9109120, 1, 1, 'Nine fish, Snack, with Otto watching. He can tell when you hide one.', 0),
(9109121, 1, 1, 'Nine more, Snack. His friends are shy.', 0),
(9109122, 1, 1, 'Nine catches, on the fjord''s beach. The war ottuk is watching from the water.', 0),
(9109130, 1, 1, 'Eight kittens. Listen. They are small, and Dalaran is loud.', 0),
(9109131, 1, 1, 'Sit with him. He talks slowly. He is very fat.', 0),
(9109140, 1, 1, 'Caw. (That means you''re slow.)', 0),
(9109141, 1, 1, 'Caw. (That means you''re slow.)', 0),
(9109142, 1, 1, 'Caw. (That means you''re slow.)', 0),
(9109143, 1, 1, 'Caw. (That means you''re slow.)', 0),
(9109144, 1, 1, 'Caw. (That means you''re slow.)', 0),
(9109145, 1, 1, 'Caw. (That means you''re slow.)', 0),
(9109146, 1, 1, 'Caw. (That means you''re slow.)', 0),
(9109150, 1, 1, 'Seven machines, and the parts. Did you turn the springy one? You turned the springy one.', 0),
(9109151, 1, 1, 'Five big ones, Snack. The plane''s just a chair with a propeller so far.', 0),
(9109160, 1, 1, 'He is waiting. He has waited a long time.', 0),
(9109161, 1, 1, 'Dawn, little horror. Not before, not after. Stand still.', 0),
(9109162, 1, 1, 'Dawn, under the mountain. He is already shouting.', 0),
(9109163, 1, 1, 'Three dawns. Patience is a thing you can eat too.', 0),
(9109164, 1, 1, 'The top of Wyrmrest. Dawn. Still. This one will hurt.', 0),
(9109165, 1, 1, 'Dawn at the Argent camp.', 0),
(9109170, 1, 1, 'Have you found the grave? He will tell you, if you ask about the mare and not about me.', 0),
(9109171, 1, 1, 'Three stalls, little horror. He walks slowly. So did he before.', 0),
(9109172, 1, 1, 'It only comes at Hallow''s End. Wait for the pumpkins.', 0),
(9109180, 1, 1, 'Five bites, and let go. Then the cauldron, before the glow gets into your eyes.', 0),
(9109181, 1, 1, 'Five ravagers. One will grin.', 0),
(9109182, 1, 1, 'Five felboars. Let them run. Then the cauldron.', 0),
(9109183, 1, 1, 'Five reavers. Mind the feet.', 0),
(9109184, 1, 1, 'Ten, where the strays can see. Then purge.', 0),
(9109185, 1, 1, 'Ten more, in Hellfire.', 0),
(9109186, 1, 1, 'Two cycles. Find the reason.', 0),
(9109190, 1, 1, 'Walk slowly, Snack. It''s a tree.', 0),
(9109191, 1, 1, 'Felwood is slow going. So is the sapling. They suit each other.', 0),
(9109192, 1, 1, 'The last walk. Slowly.', 0),
(9109193, 1, 1, 'Sit with it. Trees are slow about goodbyes.', 0),
(9109194, 1, 1, 'A little longer.', 0),
(9109200, 1, 1, 'Ten chimneys, Snack. Mind the grandmas.', 0),
(9109201, 1, 1, 'Five ingredients, and then the shooing. She is at the oven again.', 0),
(9109210, 1, 1, 'Three sets of tracks, Snack. Don''t blink.', 0),
(9109211, 1, 1, 'Keep staring, Snack!', 0),
(9109220, 1, 1, 'Sweep, Snack! They bite!', 0),
(9109221, 1, 1, 'Still, Snack! It''s trying to dunk you!', 0),
(9109222, 1, 1, 'Left! Other left!', 0),
(9109223, 1, 1, 'I am watching. Fly it properly.', 0),
(9109230, 1, 1, 'One petal, Snack. He''s waiting. Slowly.', 0),
(9109231, 1, 1, 'One petal, Snack. He''s waiting. Slowly.', 0),
(9109232, 1, 1, 'One petal, Snack. He''s waiting. Slowly.', 0),
(9109233, 1, 1, 'One petal, Snack. He''s waiting. Slowly.', 0),
(9109234, 1, 1, 'Sit on him, Snack. Slowly.', 0),
(9109235, 1, 1, 'An ember, Snack. Mind your hands.', 0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `RewardText`, `VerifiedBuild`) VALUES
(9109010, 1, 'WARM! I knew it. It''s alive in there. It''s going to need keeping warm, Snack, and you''re going to do it.$B$B|cffb87830A new form: Whelp, the Proto-Whelp Yellow colouring (or another colouring of it, if you have that one). Wear it with /devour skin Proto-Whelp Yellow.|r', 0),
(9109011, 1, 'It CRACKED! A chick! It looked at you first, Snack. That means you''re its mother. Don''t argue, it''s science.$B$BIt can''t fly. It''s going to follow you everywhere. It''ll write to you, Hagatha says; eggs that are kept warm by witches grow up literate.$B$B|cffb87830A new form: Whelp, the Red Whelp colouring (or another colouring of it, if you have that one). Wear it with /devour skin Red Whelp.|r', 0),
(9109012, 1, 'It LANDED. Next to you. Grown! Feathers and everything, or scales, I don''t know, I can''t see from here. Its last letter just said ''Look up.'' You looked up.$B$BIt wants to carry you now. That''s what grown-up chicks do for their mothers. Don''t argue. Science.', 0),
(9109013, 1, 'WARM! I knew it. It''s alive in there. It''s going to need keeping warm, Snack, and you''re going to do it.$B$B|cffb87830A new form: Owl, the Hawk Owl colouring (or another colouring of it, if you have that one). Wear it with /devour skin Hawk Owl.|r', 0),
(9109014, 1, 'It CRACKED! A chick! It looked at you first, Snack. That means you''re its mother. Don''t argue, it''s science.$B$BIt can''t fly. It''s going to follow you everywhere. It''ll write to you, Hagatha says; eggs that are kept warm by witches grow up literate.$B$B|cffb87830A new form: Owl, the Ironbeak Owl colouring (or another colouring of it, if you have that one). Wear it with /devour skin Ironbeak Owl.|r', 0),
(9109015, 1, 'It LANDED. Next to you. Grown! Feathers and everything, or scales, I don''t know, I can''t see from here. Its last letter just said ''Look up.'' You looked up.$B$BIt wants to carry you now. That''s what grown-up chicks do for their mothers. Don''t argue. Science.', 0),
(9109016, 1, 'WARM! I knew it. It''s alive in there. It''s going to need keeping warm, Snack, and you''re going to do it.$B$B|cffb87830A new form: Whelp, the Chromatic Whelp colouring (or another colouring of it, if you have that one). Wear it with /devour skin Chromatic Whelp.|r', 0),
(9109017, 1, 'It CRACKED! A chick! It looked at you first, Snack. That means you''re its mother. Don''t argue, it''s science.$B$BIt can''t fly. It''s going to follow you everywhere. It''ll write to you, Hagatha says; eggs that are kept warm by witches grow up literate.$B$B|cffb87830A new form: Whelp, the Armored Whelp colouring (or another colouring of it, if you have that one). Wear it with /devour skin Armored Whelp.|r', 0),
(9109018, 1, 'It LANDED. Next to you. Grown! Feathers and everything, or scales, I don''t know, I can''t see from here. Its last letter just said ''Look up.'' You looked up.$B$BIt wants to carry you now. That''s what grown-up chicks do for their mothers. Don''t argue. Science.', 0),
(9109020, 1, 'All five! The dream took shape, didn''t it? That''s the dreamweavers of the forest, come out of the dream to see who was touching its shards.$B$BHere. Hagatha says the other colours of this dream come from the Breeding Pen.', 0),
(9109021, 1, 'All five! The dream took shape, didn''t it? That''s the tangled dreamers, come out of the dream to see who was touching its shards.$B$BHere. Hagatha says the other colours of this dream come from the Breeding Pen.', 0),
(9109022, 1, 'All five! The dream took shape, didn''t it? That''s the wintertide dreamers, come out of the dream to see who was touching its shards.$B$BHere. Hagatha says the other colours of this dream come from the Breeding Pen.', 0),
(9109023, 1, 'All five! The dream took shape, didn''t it? That''s the dreamers of the floating plains, come out of the dream to see who was touching its shards.$B$BHere. Hagatha says the other colours of this dream come from the Breeding Pen.', 0),
(9109024, 1, 'All five! The dream took shape, didn''t it? That''s the fey dreamers, come out of the dream to see who was touching its shards.$B$BHere. Hagatha says the other colours of this dream come from the Breeding Pen.', 0),
(9109025, 1, 'She came. Of course she came; you smelled of five dreams at once.$B$BTake the reins. Do not ride her into a wall.', 0),
(9109030, 1, 'You smelled it. Now you will smell it everywhere: buried fragments, buttons, map scraps, all over the world, wherever Sniff shows a glint.$B$BDig them up as you go. Wren keeps the tally and pays in runners.$B$B|cffb87830A new form: Trogg, the Rockjaw colouring (or another colouring of it, if you have that one). Wear it with /devour skin Rockjaw.|r', 0),
(9109031, 1, 'That''s it, that''s one of mine! Now you know the smell. Bring me the rest whenever you find them; I''ve got prizes from the fair for every handful, and a turkey for the first lot.$B$B|cffb87830A new form: Wolf, the Timber colouring (or another colouring of it, if you have that one). Wear it with /devour skin Timber.|r', 0),
(9109032, 1, 'Silithus. Of course. She went where the diary said NOT to go, three times over. Hagatha says the scorpids have her. Hagatha says it like it''s funny.$B$B|cffb87830A new form: Wolf, the Scavenger colouring (or another colouring of it, if you have that one). Wear it with /devour skin Scavenger.|r', 0),
(9109033, 1, '''Under control.'' She said it! Hagatha owes me a spoon.$B$BThe camels came home with you. One of them is yours now; the explorer says she can''t afford to feed three. Here''s its reins, and her dunetrekker''s, which she''s lending you forever.', 0),
(9109034, 1, 'They stopped laughing. Then one of them came and sat on your foot. That''s a hyena saying yes.$B$BHere''s its reins. It still laughs in its sleep.', 0),
(9109050, 1, 'Light. The cauldron drinks it. Something stirs at the bottom, little horror. It will need more.', 0),
(9109051, 1, 'It climbed out. Did you see its eyes? It remembers the one it carried, and it has decided you will do.', 0),
(9109052, 1, 'Three lights. Three steeds. The cauldron is nearly full; one more and it opens.', 0),
(9109053, 1, 'The cauldron opened. They climbed out, all of them, with the names of the ones they carried. They are yours now, little horror. Wren says they are not scary. Wren is wrong, and right.', 0),
(9109060, 1, 'The oldest of them followed you out, and it is still following. It thinks you are its young. Let it.$B$BTake the reins. The other colours come from the Breeding Pen, as always.', 0),
(9109061, 1, 'The oldest of them followed you out, and it is still following. It thinks you are its young. Let it.$B$BTake the reins. The other colours come from the Breeding Pen, as always.', 0),
(9109062, 1, 'The oldest of them followed you out, and it is still following. It thinks you are its young. Let it.$B$BTake the reins. The other colours come from the Breeding Pen, as always.', 0),
(9109063, 1, 'The oldest of them followed you out, and it is still following. It thinks you are its young. Let it.$B$BTake the reins. The other colours come from the Breeding Pen, as always.', 0),
(9109064, 1, 'The oldest of them followed you out, and it is still following. It thinks you are its young. Let it.$B$BTake the reins. The other colours come from the Breeding Pen, as always.', 0),
(9109065, 1, 'The oldest of them followed you out, and it is still following. It thinks you are its young. Let it.$B$BTake the reins. The other colours come from the Breeding Pen, as always.', 0),
(9109066, 1, 'The oldest of them followed you out, and it is still following. It thinks you are its young. Let it.$B$BTake the reins. The other colours come from the Breeding Pen, as always.', 0),
(9109070, 1, 'It crawled out. A slimesaber, and it has already decided it is yours. Wren named it. I will not repeat the name.', 0),
(9109071, 1, 'It crawled out. A parasite that wriggles, and it has already decided it is yours. Wren named it. I will not repeat the name.', 0),
(9109072, 1, 'It crawled out. A cormaera, still smouldering, and it has already decided it is yours. Wren named it. I will not repeat the name.', 0),
(9109073, 1, 'It crawled out. A saprophyte amalgam, and it has already decided it is yours. Wren named it. I will not repeat the name.', 0),
(9109074, 1, 'It crawled out. A bloodgorged crawg, and it has already decided it is yours. Wren named it. I will not repeat the name.', 0),
(9109075, 1, 'It crawled out. A chimeric embryo, and it has already decided it is yours. Wren named it. I will not repeat the name.', 0),
(9109076, 1, 'It crawled out. The prismatic slimesaber, and it has already decided it is yours. Wren named it. I will not repeat the name.', 0),
(9109080, 1, 'It looked at you, and you looked back, and you ate it. Good. The thin place is a little thicker now, and you are a little thinner.$B$BTake what it left.', 0),
(9109081, 1, 'It looked at you, and you looked back, and you ate it. Good. The thin place is a little thicker now, and you are a little thinner.$B$BTake what it left.', 0),
(9109082, 1, 'It looked at you, and you looked back, and you ate it. Good. The thin place is a little thicker now, and you are a little thinner.$B$BTake what it left.', 0),
(9109083, 1, 'It looked at you, and you looked back, and you ate it. Good. The thin place is a little thicker now, and you are a little thinner.$B$BTake what it left.', 0),
(9109084, 1, 'It looked at you, and you looked back, and you ate it. Good. The thin place is a little thicker now, and you are a little thinner.$B$BTake what it left.', 0),
(9109085, 1, 'They came: the bat, the gryphon, the hippogryph, the wyvern, and the one that would not go home. Voidbound, all of them, and bound to you now.$B$BRide carefully. They remember the other side.', 0),
(9109086, 1, 'They settled. Everything settles, once it has seen you eat.$B$BTake the reins.', 0),
(9109090, 1, 'I saw them. Booty Bay. Hm. Smells like that from here.$B$BWren pinned them up over the cauldron. The courier that brought your companions'' letters about them wants to stay. So does the pirate''s horse from the bay; it followed the smell.$B$B|cffb87830A new form: Owl, the Strigid Owl colouring (or another colouring of it, if you have that one). Wear it with /devour skin Strigid Owl.|r', 0),
(9109091, 1, 'Six postcards. Wren has pinned them up and is drawing on them. The courier and the cutlass''s horse are yours; I have no use for a horse, and the courier eats too much.', 0),
(9109100, 1, 'All four! The whole coast is winking. Now the pier. Go and watch.$B$B|cffb87830A new form: Spikeshell, the Dragon Turtle colouring (or another colouring of it, if you have that one). Wear it with /devour skin Dragon Turtle.|r', 0),
(9109101, 1, 'An EEL. With lightning in it! And it let you pat it! And it followed you home!$B$BHere''s its reins. Hagatha says there are more down there, and they''ll come if you keep the lights lit.', 0),
(9109102, 1, 'Three of them, patted, and they all followed you home. The pier''s going to need a bigger pier.$B$BHere: the snapdragon''s reins and the others''. The salamanther is pink. Don''t tell Hagatha it''s pink.', 0),
(9109103, 1, 'It came, and you ate it, and the tuskarr''s shoreglider came to see what ate it. Both are yours.$B$BTake the reins.', 0),
(9109110, 1, 'Rung, and the bears came. Arktos, the great bear followed you down, and it is yours.$B$BTake the reins.', 0),
(9109111, 1, 'Rung, and the yaks came. A grey riding yak and a wilderling followed you down, and it is yours.$B$BTake the reins.', 0),
(9109112, 1, 'Rung, and the mammoths came. A plainswalker bearer followed you down, and it is yours.$B$BTake the reins.', 0),
(9109113, 1, 'Rung, and the storm came. An alabaster thunderwing followed you down, and it is yours.$B$BTake the reins.', 0),
(9109114, 1, 'The storm came down. A blizzard with a will, a tidestorm, and the Valarjar''s own stormwing, all three, to see who rang. They saw. They stayed.$B$BTake the reins. Ride the storm quietly.', 0),
(9109120, 1, 'Nine fish and Otto''s your friend for life. He followed you up the beach! Here''s his reins. Yes, you can ride an ottuk. He insists.', 0),
(9109121, 1, 'They CAME. A crab the size of a cart, a plodder, a riverbeast, all sitting on the beach eating your fish. Here are all their reins. Otto arranged it. Otto''s very organised.', 0),
(9109122, 1, 'It came, and ate, and knelt, which is how an ottuk says ''I will carry you''. The crest-horn and the thundertrotter came after it; they follow the war ottuk everywhere.$B$BTake the reins.', 0),
(9109130, 1, 'Eight, patted, and every one of them went home ahead of you. The father is beside himself; he has eaten two whole fish in relief.$B$BHe says his brother will carry you, by way of thanks. His brother is as fat as he is. Take the reins.', 0),
(9109131, 1, 'He talked for an hour about his kittens, and then he gave you the furline and the moon cat, and then he went to sleep.$B$BTake the reins. Visit him sometimes.', 0),
(9109140, 1, 'Got it! And a riddle: ''The next page lies where a wizard''s tower looks down on a pass the dead walk through, and nobody goes in.''$B$B|cffb87830A new form: Vampiric Duskbat, the Vampiric colouring (or another colouring of it, if you have that one). Wear it with /devour skin Vampiric.|r', 0),
(9109141, 1, 'Got it! And a riddle: ''The next page lies in a city that floats, in the hall where the violet books are kept.''$B$B|cffb87830A new form: Whelp, the Nightmare Whelp colouring (or another colouring of it, if you have that one). Wear it with /devour skin Nightmare Whelp.|r', 0),
(9109142, 1, 'Got it! And a riddle: ''The next page lies on a tier of seers, in a city of light with a naaru at its heart.''$B$B|cffb87830A new form: Whelp, the Ley Whelp colouring (or another colouring of it, if you have that one). Wear it with /devour skin Ley Whelp.|r', 0),
(9109143, 1, 'Got it! And a riddle: ''The next page lies in a monastery that burns things, under the Scarlet eye.''$B$B|cffb87830A new form: Warp Stalker, the Warp Stalker colouring (or another colouring of it, if you have that one). Wear it with /devour skin Warp Stalker.|r', 0),
(9109144, 1, 'Got it! And a riddle: ''The next page lies under the mountain, with the explorers and their bones.''$B$B|cffb87830A new form: Owl, the Shadowwing Owl colouring (or another colouring of it, if you have that one). Wear it with /devour skin Shadowwing Owl.|r', 0),
(9109145, 1, 'Got it! And a riddle: ''The next page lies under the ruins, where the dead read in the dark.''$B$B|cffb87830A new form: Whelp, the Bronze Whelp colouring (or another colouring of it, if you have that one). Wear it with /devour skin Bronze Whelp.|r', 0),
(9109146, 1, 'The LAST PAGE. The book''s whole. It... it''s flapping. It flies! It flies badly! Hagatha''s furious and delighted at once.$B$BThe book is yours; Hagatha won''t touch it now that it''s been in Undercity. And Pilfer''s cousin, the flame-touched raven, has been following you since Karazhan. And the scribe''s bear that carried the book in the first place wants to carry it, and you, again.', 0),
(9109150, 1, 'Parts! Gears and pipes and the springy things! Here, I built two already: a buzzsaw on wheels and a jungle hopper. The hopper hops. The buzzsaw... duck.', 0),
(9109151, 1, 'It FLIES. The plane flies, the propulsor propels, and the reactor... hums. Keep the reactor away from the cauldron.$B$BHere are the keys to all three. Mostly safe.', 0),
(9109160, 1, 'Five pieces, and the truth told. He is standing straighter already.$B$BNow for the horse.$B$B|cffb87830A new form: Owl, the Skethyl Owl colouring (or another colouring of it, if you have that one). Wear it with /devour skin Skethyl Owl.|r', 0),
(9109161, 1, 'He rode. Once, around the chapel, and the light took him. The horse stayed; it is yours, as it was always going to be.$B$BThe squires'' mounts came out of the memory with it: a vorquin, a frostcharger. They follow the knight''s horse everywhere.', 0),
(9109162, 1, 'He shouted, he rode, he shouted some more, and the mountain took him back. The Dawnforge ram is yours.', 0),
(9109163, 1, 'Three memories, pulled out and standing. The chapel is getting crowded with your horses.$B$BTake the reins.', 0),
(9109164, 1, 'It came out of you like a sunrise, and it did not go anywhere. It had been waiting to be remembered.$B$BTyrael''s charger, the seraph''s, the lord of steeds: they are yours. Nothing you have eaten will ever be grander than that.', 0),
(9109165, 1, 'Two more memories, standing in the Argent camp, looking embarrassed. Take the reins.', 0),
(9109170, 1, 'The mare''s ghost came up out of the dirt, looked at Tam, looked at you, and chose you. He cried. Forsaken can, it turns out.$B$BShe is yours. Visit him. And never ask me how I knew him.', 0),
(9109171, 1, 'He said goodbye three times, and three times something came out of a stall and stood beside you. He is sitting on the fence now, looking almost happy.$B$BTake the reins.', 0),
(9109172, 1, 'A pumpkin. It hates that one. The charger is yours; it chills everything it stands on, and it says the Horseman can walk.', 0),
(9109180, 1, 'Five helboars, clean, and a Devourer glowing green at the knees. Purged. Vessa sent the first of them along: a gnasher with the fel gone out of it, and a felflame talbuk that followed it.$B$BTake the reins.', 0),
(9109181, 1, 'One grinned. Vessa says it followed her home and will not stop grinning. It is yours now, grin and all.', 0),
(9109182, 1, 'Five, calmed, fled, found. Vessa sent the hounds and a fel beast along with her thanks; the fel is out of them and they do not know what to do with themselves. Carry you, probably.', 0),
(9109183, 1, 'Five machines, talked out of a war that ended years ago. They let you drive. The deathcycles came with them; they were never told either.$B$BTake the keys. All of them.', 0),
(9109184, 1, 'They saw, and they came. Every stray Vessa ever fed. Take the reins and the keys; there are a great many of them, and none of them are glowing any more.', 0),
(9109185, 1, 'The last of them. Vessa says the plain is quiet now. She says it like she misses the noise.', 0),
(9109186, 1, 'Both cycles started. Loudly. Take the keys.', 0),
(9109190, 1, 'It drank, and it GREW. Look at it. Twice the size. Still slow.$B$B|cffb87830A new form: Saber, the Lynx colouring (or another colouring of it, if you have that one). Wear it with /devour skin Lynx.|r', 0),
(9109191, 1, 'It grew again, and a MOOSE joined you, with its whole herd. The sapling likes the moose. The moose likes the sapling. Here''s the moose''s reins; it says it''s yours now, as long as the sapling comes too.', 0),
(9109192, 1, 'It''s HOME. It''s an Ancient now, a whole Ancient, and it put down roots where the old one stood, and then it pulled one root up again and offered you a branch.$B$BThe branch carries you. Its forest friends came to see: stags, elderhorns, a grove crawler, a chloroceros, a carnivarus. They''re all yours. The forest says so.', 0),
(9109193, 1, 'They came, all of them. The forest is yours now, in instalments.$B$BTake the reins.', 0),
(9109194, 1, 'The chloroceros and the carnivarus. The carnivarus bites. Only things you don''t like.', 0),
(9109200, 1, 'Ten presents, delivered! One grandma threw a boot. Here''s your present: a reindeer with a thorn in its hoof, and a toy train. The train goes round. Only round.', 0),
(9109201, 1, 'Baked. Mildly munched; she got to it once. It still runs, if a little lopsided. The blizzard bear and Grumpus''s minion came in with the cold, and the candy copter is Wren''s; she says you can have it if you forgive the hoof.', 0),
(9109210, 1, 'Mulgore! It''s cornered itself by the Spring Gatherer''s dead end. Go and STARE.$B$B|cffb87830A new form: Plainstrider, the Tallstrider colouring (or another colouring of it, if you have that one). Wear it with /devour skin Tallstrider.|r', 0),
(9109211, 1, 'It CRACKED. A serpent climbed out, very offended, and a second one after it, even more offended. They''re yours; they''ve decided it''s your fault.', 0),
(9109220, 1, 'The broom liked that. It''s still cross, but it liked it. Lesson two next.$B$B|cffb87830A new form: Voidling, the Voidling colouring (or another colouring of it, if you have that one). Wear it with /devour skin Voidling.|r', 0),
(9109221, 1, 'Not dunked! Mostly! The broom''s impressed. The ducks are not.$B$B|cffb87830A new form: Whelp, the Blue Whelp colouring (or another colouring of it, if you have that one). Wear it with /devour skin Blue Whelp.|r', 0),
(9109222, 1, 'You passed! The broom''s yours! It''s still cross but it''s YOUR cross broom now.', 0),
(9109223, 1, 'Adequate. The Sweepers are yours. Do not let Wren teach them anything.', 0),
(9109230, 1, 'He ate it! Look at the shell! It''s gone the colour of the season! He''s sleeping it off. Next season after.$B$B|cffb87830A new form: Boar, the Thistle colouring (or another colouring of it, if you have that one). Wear it with /devour skin Thistle.|r', 0),
(9109231, 1, 'He ate it! Look at the shell! It''s gone the colour of the season! He''s sleeping it off. Next season after.$B$B|cffb87830A new form: Whelp, the Green Whelp colouring (or another colouring of it, if you have that one). Wear it with /devour skin Green Whelp.|r', 0),
(9109232, 1, 'He ate it! Look at the shell! It''s gone the colour of the season! He''s sleeping it off. Next season after.$B$B|cffb87830A new form: Saber, the Springpaw colouring (or another colouring of it, if you have that one). Wear it with /devour skin Springpaw.|r', 0),
(9109233, 1, 'He ate it! Look at the shell! It''s gone the colour of the season! He''s sleeping it off. Next season after.$B$B|cffb87830A new form: Wolf, the Grey colouring (or another colouring of it, if you have that one). Wear it with /devour skin Grey.|r', 0),
(9109234, 1, 'He carried you! Slowly! Here''s his reins. If you want him another colour, feed him another season; the Breeding Pen knows how.', 0),
(9109235, 1, 'It came up! A slug of magma, glowing, and a magmashell behind it, and they''re both yours. Don''t bring them near Mister Slow; he''s jealous.', 0);
